-- NOTE: This migration was originally auto-generated by `prisma migrate dev`
-- and tried to DROP the pg_trgm indexes `merchants_name_trgm_idx` and
-- `products_name_trgm_idx`. Those indexes are created by raw SQL in
-- 20260512100000_phase6_addresses_banners_trgm and are not represented in the
-- Prisma schema, so Prisma's diff keeps wanting to drop them. Dropping them
-- breaks merchant/product full-text search.
--
-- The DROPs were neutralized after the fact. CREATE IF NOT EXISTS is kept
-- here so that fresh databases re-applying all migrations end up with the
-- indexes present.

CREATE INDEX IF NOT EXISTS "merchants_name_trgm_idx"
  ON "merchants" USING GIN ("name" gin_trgm_ops);

CREATE INDEX IF NOT EXISTS "products_name_trgm_idx"
  ON "products" USING GIN ("name" gin_trgm_ops);
